using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using XanaduYonder.Core.LinkMatch;
using XanaduYonder.Runtime.LinkMatch;

internal static class Program
{
    private static int passed;
    private static void Main()
    {
        Check("preview does not create attempts", () => { var p = new LinkMatchProfile(); p.SelectedMode = LinkMatchMode.Challenge; p.SelectedLevelId = "level-03"; var d = Decode(LinkMatchSaveCodec.Encode(p.Export())); Assert(d.Slots.All(x => x == null)); Assert(p.GetLatestActive() == null); Eq(p.CompletedCount, 0); });
        Check("effective clock requires ready visible foreground unblocked session", () => { var s = New(); s.Tick(5); Eq(s.ElapsedSeconds, 0); s.Enter(); s.Tick(2); s.SetBlocked(true); s.Tick(20); s.SetBlocked(false); s.Tick(3); s.Leave(); s.Tick(20); s.Enter(); s.SetForeground(false); s.Tick(20); s.SetForeground(true); s.Tick(20); Eq(s.ElapsedSeconds, 5); Assert(!s.CanInteract); s.SetBlocked(false); s.Tick(1); Eq(s.ElapsedSeconds, 6); });
        Check("invalid deltas cannot corrupt the clock", () => { var s = New(); s.Enter(); foreach (double n in new[] { -1d, double.NaN, double.PositiveInfinity }) Throws(() => s.Tick(n)); Eq(s.ElapsedSeconds, 0); });
        Check("challenge exact deadline rejects match hint shuffle", () => { var s = LastPair(LinkMatchMode.Challenge, 89); s.Enter(); s.Tick(1); Assert(s.Outcome == LinkMatchOutcome.TimedOut); Assert(!s.TryMatch(0, 1, out var path)); Assert(s.TryHint() == null && !s.TryShuffle()); Eq(s.RemainingSeconds, 0); Eq(s.Game.Remaining, 2); });
        Check("last pair wins at acceptance and cannot time out in feedback", () => { var s = LastPair(LinkMatchMode.Challenge, 89.99); s.Enter(); Assert(s.TryMatch(0, 1, out var path)); Assert(s.Outcome == LinkMatchOutcome.Won); s.Tick(10); Eq(s.ElapsedSeconds, 89.99); Assert(!s.TryMatch(0, 1, out path)); });
        Check("relaxed mode has no timeout and unlimited assistance", () => { var s = New(); s.Enter(); s.Tick(1000); for (int i = 0; i < 5; i++) Assert(s.TryHint() != null && s.TryShuffle()); Assert(s.Outcome == LinkMatchOutcome.Playing); Eq(s.HintsUsed, 5); Eq(s.ShufflesUsed, 5); });
        Check("challenge quotas charge only successful interactive assistance", () => { var s = New(LinkMatchMode.Challenge); Assert(s.TryHint() == null && !s.TryShuffle()); s.Enter(); for (int i = 0; i < 3; i++) Assert(s.TryHint() != null); Assert(s.TryHint() == null); for (int i = 0; i < 2; i++) Assert(s.TryShuffle()); Assert(!s.TryShuffle()); Eq(s.HintsRemaining, 0); Eq(s.ShufflesRemaining, 0); s.Tick(2); Eq(s.ElapsedSeconds, 2); });
        Check("restoration freezes time and preserves deterministic next shuffle", () => { var a = New(); a.Enter(); a.TryShuffle(); a.Tick(7.25); var b = new LinkMatchSession(a.Export()); b.Tick(100); Eq(b.ElapsedSeconds, 7.25); b.Enter(); Assert(a.TryShuffle() && b.TryShuffle()); Assert(a.Game.GetTiles().SequenceEqual(b.Game.GetTiles())); });
        Check("automatic no-move rescue is free and preserves multiset", () => { var d = New(LinkMatchMode.Challenge).Export(); d.Tiles = Enumerable.Repeat(-1, 24).ToArray(); d.Tiles[5] = 0; d.Tiles[6] = 1; d.Tiles[9] = 1; d.Tiles[10] = 0; var s = new LinkMatchSession(d); s.Enter(); Assert(s.Game.FindMatch() == null); Assert(s.EnsureMove()); Assert(s.Game.FindMatch() != null); Eq(s.ShufflesUsed, 0); Eq(s.ElapsedSeconds, 0); Assert(s.Game.GetTiles().OrderBy(x => x).SequenceEqual(d.Tiles.OrderBy(x => x))); Assert(!s.EnsureMove()); });
        Check("six independent slots resume and latest excludes terminal slots", () => { var p = new LinkMatchProfile(); for (int m = 0; m < 2; m++) for (int l = 1; l <= 3; l++) { var s = p.Start((LinkMatchMode)m, LinkMatchLevel.Get(l).Id, (uint)(l + m)); s.Enter(); s.Tick(l); p.Capture(s); } Eq(p.Export().Slots.Count(x => x != null), 6); var latest = p.GetLatestActive(); Assert(latest.Mode == LinkMatchMode.Challenge && latest.LevelId == "level-03"); var resumed = p.Start(LinkMatchMode.Relaxed, "level-01", 99); Eq(resumed.ElapsedSeconds, 1); Assert(p.GetLatestActive().AttemptId == resumed.AttemptId); var other = p.GetSlot(LinkMatchMode.Relaxed, "level-02"); var fresh = p.Start(LinkMatchMode.Relaxed, "level-01", 99, true); Assert(fresh.AttemptId != resumed.AttemptId && other.AttemptId == p.GetSlot(LinkMatchMode.Relaxed, "level-02").AttemptId); Throws(() => p.Capture(resumed)); });
        Check("snapshots never expose mutable board arrays", () => { var p = new LinkMatchProfile(); var s = p.Start(LinkMatchMode.Relaxed, "level-01", 5); var d = s.Export(); d.Tiles[0] = -1; Assert(s.Game.TileAt(0) != -1); var saved = p.Export(); saved.Slots[0].Tiles[0] = -1; Assert(p.GetSlot(LinkMatchMode.Relaxed, "level-01").Tiles[0] != -1); });
        Check("win capture and restored copies cannot double count", () => { var s = LastPair(LinkMatchMode.Challenge, 6); var p = new LinkMatchProfile(); p.Capture(s); s.Enter(); s.TryMatch(0, 1, out var path); var unrecorded = s.Export(); p.Capture(s); p.Capture(s); p.Capture(new LinkMatchSession(unrecorded)); Eq(p.GetRecord(s.Mode, "level-01").Wins, 1); Eq(p.CompletedCount, 1); Assert(p.GetLatestActive() == null); Assert(s.ResultRecorded); var q = new LinkMatchProfile(Decode(LinkMatchSaveCodec.Encode(p.Export()))); q.Capture(new LinkMatchSession(q.GetSlot(s.Mode, "level-01"))); Eq(q.GetRecord(s.Mode, "level-01").Wins, 1); });
        Check("best record keeps time and aids from the same winning attempt", () => { var p = new LinkMatchProfile(); Win(p, 10, 2, 1); var first = p.GetRecord(LinkMatchMode.Challenge, "level-01"); Win(p, 20, 0, 0); var slower = p.GetRecord(LinkMatchMode.Challenge, "level-01"); Eq(slower.BestElapsedSeconds.Value, 10); Eq(slower.BestHintsUsed, 2); Assert(slower.BestAttemptId == first.BestAttemptId); Win(p, 5, 1, 2); var best = p.GetRecord(LinkMatchMode.Challenge, "level-01"); Eq(best.Wins, 3); Eq(best.BestElapsedSeconds.Value, 5); Eq(best.BestHintsUsed, 1); Eq(best.BestShufflesUsed, 2); });
        Check("timeout capture is idempotent and does not produce a best", () => { var p = new LinkMatchProfile(); var s = p.Start(LinkMatchMode.Challenge, "level-01", 1); s.Enter(); s.Tick(100); p.Capture(s); p.Capture(s); var r = p.GetRecord(s.Mode, "level-01"); Eq(r.Losses, 1); Eq(r.Wins, 0); Assert(!r.BestElapsedSeconds.HasValue && p.GetLatestActive() == null); });
        Check("all required fields and unknown fields are strictly checked", () => { var root = JObject.Parse(LinkMatchSaveCodec.Encode(Fixture())); foreach (var path in new[] { "", "slots[0]", "records[0]" }) { var obj = path == "" ? root : (JObject)root.SelectToken(path); foreach (var property in obj.Properties()) { var copy = (JObject)root.DeepClone(); (path == "" ? copy : (JObject)copy.SelectToken(path)).Remove(property.Name); Reject(copy.ToString()); } var extra = (JObject)root.DeepClone(); (path == "" ? extra : (JObject)extra.SelectToken(path))["unknown"] = 1; Reject(extra.ToString()); } });
        Check("JSON malformed duplicate comments trailing commas and text reject", () => { var j = LinkMatchSaveCodec.Encode(Fixture()); Reject(j + "{}"); Reject(j.Replace("\"schemaVersion\":1", "\"schemaVersion\":1,\"schemaVersion\":1")); Reject(j.Replace("\"schemaVersion\"", "'schemaVersion'")); Reject(j.Replace("\"schemaVersion\":1", "\"schemaVersion\":1/*x*/")); Reject(j.Substring(0, j.Length - 1) + ",}"); Reject("null"); });
        Check("null wrong scalar types and unknown identifiers reject", () => { foreach (var path in new[] { "schemaVersion", "slots[0].columns", "slots[0].rows", "slots[0].hintsUsed", "slots[0].randomState", "records[0].wins" }) foreach (var token in new JToken[] { JValue.CreateNull(), new JValue("1"), new JValue(1.5), new JValue(-1) }) Mutate(path, token); Mutate("slots[0].mode", new JValue("other")); Mutate("slots[0].levelId", new JValue("01")); Mutate("slots[0].outcome", new JValue("Paused")); Mutate("slots[0].resultRecorded", new JValue(1)); Mutate("slots[0].attemptId", new JValue("invalid")); Mutate("contentVersion", new JValue("future")); });
        Check("board null length values and parity reject but legitimate deadlock loads", () => { Mutate("slots[0].tiles", JValue.CreateNull()); Mutate("slots[0].tiles", new JArray()); Mutate("slots[0].tiles[0]", JValue.CreateNull()); Mutate("slots[0].tiles[0]", new JValue(99)); var d = Fixture(); var a = d.Slots[0]; a.Tiles = Enumerable.Repeat(-1, 24).ToArray(); a.Tiles[5] = 0; a.Tiles[6] = 1; a.Tiles[9] = 1; a.Tiles[10] = 0; Decode(LinkMatchSaveCodec.Encode(d)); a.Tiles[5] = -1; Throws(() => LinkMatchSaveCodec.Encode(d)); });
        Check("clock quotas result flags and records agree with terminal board", () => { foreach (var t in new JToken[] { JValue.CreateNull(), new JValue("0"), new JValue(-1), new JValue(double.NaN) }) Mutate("slots[0].elapsedSeconds", t); Mutate("slots[0].remainingSeconds", new JValue(3)); Mutate("slots[0].outcome", new JValue("Won")); Mutate("slots[0].resultRecorded", new JValue(true)); Mutate("records[0].wins", new JValue(1)); var p = new LinkMatchProfile(); var s = LastPair(LinkMatchMode.Challenge, 10); s.Enter(); s.TryMatch(0, 1, out var path); p.Capture(s); var root = JObject.Parse(LinkMatchSaveCodec.Encode(p.Export())); root["records"][3]["bestElapsedSeconds"] = 20; Reject(root.ToString()); root = JObject.Parse(LinkMatchSaveCodec.Encode(p.Export())); root["slots"][3]["resultRecorded"] = false; Reject(root.ToString()); });
        Check("bounded JSON rejects huge UTF8 size and nested containers", () => { Reject(new string(' ', LinkMatchSaveCodec.MaximumLength + 1)); Reject("{\"x\":\"" + new string('汉', LinkMatchSaveCodec.MaximumLength / 2) + "\"}"); Reject(new string('[', 30) + "0" + new string(']', 30)); });
        Check("real storage atomic replacement keeps previous valid backup", () => WithDirectory(dir => { var s = new LinkMatchSaveStore(dir); Assert(s.Load(out var warning) == null && warning == null); var d = Fixture(); Assert(s.TrySave(d, out var error), error); d.SelectedLevelId = "level-03"; Assert(s.TrySave(d, out error), error); Assert(!File.Exists(s.SavePath + ".tmp")); Assert(s.Load(out warning).SelectedLevelId == "level-03"); Assert(Decode(File.ReadAllText(s.SavePath + ".bak")).SelectedLevelId == "level-01"); }));
        Check("corrupt primary recovers backup and never promotes corruption", () => WithDirectory(dir => { var s = new LinkMatchSaveStore(dir); Assert(s.TrySave(Fixture(), out var error), error); Assert(s.TrySave(Fixture(), out error), error); var backup = File.ReadAllText(s.SavePath + ".bak"); File.WriteAllText(s.SavePath, "broken"); var recovered = s.Load(out var warning); Assert(recovered != null && warning != null); Assert(Directory.GetFiles(dir, "*.corrupt-*").Length > 0); Assert(s.TrySave(recovered, out error), error); Assert(File.ReadAllText(s.SavePath + ".bak") == backup); Assert(s.Load(out warning) != null && warning == null); }));
        Check("double corrupt invalid UTF8 and oversized files give recovery warnings", () => WithDirectory(dir => { var s = new LinkMatchSaveStore(dir); File.WriteAllBytes(s.SavePath, new byte[] { 0xff, 0xfe }); File.WriteAllText(s.SavePath + ".bak", "null"); Assert(s.Load(out var warning) == null && warning != null); File.WriteAllBytes(s.SavePath, new byte[LinkMatchSaveCodec.MaximumLength + 1]); Assert(s.Load(out warning) == null && warning != null); }));
        Check("save failure retains in-memory result and retry cannot double count", () => WithDirectory(dir => { string blocked = Path.Combine(dir, "blocked"); File.WriteAllText(blocked, "file"); var s = new LinkMatchSaveStore(blocked); var p = new LinkMatchProfile(); Win(p, 4, 1, 1); Assert(!s.TrySave(p.Export(), out var error) && error != null); Eq(p.GetRecord(LinkMatchMode.Challenge, "level-01").Wins, 1); File.Delete(blocked); Assert(s.TrySave(p.Export(), out error), error); Eq(s.Load(out var warning).Records[3].Wins, 1); }));
        Check("unrelated game files and committed save survive rejected writes", () => WithDirectory(dir => { string other = Path.Combine(dir, "sokoban-v1.json"); File.WriteAllText(other, "untouched"); var s = new LinkMatchSaveStore(dir); var d = Fixture(); Assert(s.TrySave(d, out var error), error); string before = File.ReadAllText(s.SavePath); d.Slots[0].HintsUsed = -1; Assert(!s.TrySave(d, out error) && error != null); Assert(File.ReadAllText(s.SavePath) == before); Assert(File.ReadAllText(other) == "untouched"); }));
        Check("invalid DTO reports a useful reason instead of silently returning false", () => { var d = Fixture(); d.Records[0] = null; Assert(!d.TryValidate(out var reason)); Assert(!string.IsNullOrWhiteSpace(reason), "Null record was rejected without a boundary error"); });
        Check("all six slots and terminal tuples survive a single disk roundtrip", () => { var p = new LinkMatchProfile(); for (int m = 0; m < 2; m++) for (int l = 1; l <= 3; l++) p.Start((LinkMatchMode)m, LinkMatchLevel.Get(l).Id, (uint)(m * 3 + l)); var timedOut = p.Start(LinkMatchMode.Challenge, "level-03", 99); timedOut.Enter(); timedOut.Tick(150); p.Capture(timedOut); Win(p, 11.125, 3, 2); var q = new LinkMatchProfile(Decode(LinkMatchSaveCodec.Encode(p.Export()))); Eq(q.Export().Slots.Count(x => x != null), 6); Assert(q.GetSlot(LinkMatchMode.Challenge, "level-03").Outcome == LinkMatchOutcome.TimedOut); Eq(q.GetRecord(LinkMatchMode.Challenge, "level-01").BestElapsedSeconds.Value, 11.125); Assert(q.GetLatestActive().LevelId == "level-02" && q.GetLatestActive().Mode == LinkMatchMode.Challenge); });
        Check("overflow numeric tokens and challenge quota violations reject", () => { var json = LinkMatchSaveCodec.Encode(Fixture()); Reject(json.Replace("\"schemaVersion\":1", "\"schemaVersion\":999999999999999999999999999999999999")); Reject(json.Replace("4.25", "1e400")); var p = new LinkMatchProfile(); p.Start(LinkMatchMode.Challenge, "level-01", 1); var original = JObject.Parse(LinkMatchSaveCodec.Encode(p.Export())); foreach (var pair in new[] { new { Field = "hintsUsed", Value = 4 }, new { Field = "shufflesUsed", Value = 3 }, new { Field = "elapsedSeconds", Value = 91 } }) { var root = (JObject)original.DeepClone(); root["slots"][3][pair.Field] = pair.Value; Reject(root.ToString()); } });
        Check("activity order overflow preserves latest ordering without wall time", () => { var p = new LinkMatchProfile(); p.Start(LinkMatchMode.Relaxed, "level-01", 1); p.Start(LinkMatchMode.Relaxed, "level-02", 2); var d = p.Export(); d.ActivitySequence = long.MaxValue; p = new LinkMatchProfile(d); var session = p.Start(LinkMatchMode.Relaxed, "level-03", 3); Assert(p.GetLatestActive().AttemptId == session.AttemptId); Assert(p.Export().ActivitySequence < 10); Decode(LinkMatchSaveCodec.Encode(p.Export())); });
        Check("primary corrupted after load never replaces a known valid backup", () => WithDirectory(dir => { var store = new LinkMatchSaveStore(dir); var d = Fixture(); Assert(store.TrySave(d, out var error), error); d.SelectedLevelId = "level-02"; Assert(store.TrySave(d, out error), error); Assert(store.Load(out var warning) != null); var backup = File.ReadAllText(store.SavePath + ".bak"); File.WriteAllText(store.SavePath, "[]"); Assert(store.TrySave(d, out error), error); Assert(File.ReadAllText(store.SavePath + ".bak") == backup); Assert(store.Load(out warning).SelectedLevelId == "level-02"); }));
        Check("preview selection survives background capture of the previous session", () => { var p = new LinkMatchProfile(); var s = p.Start(LinkMatchMode.Relaxed, "level-01", 5); s.Enter(); s.Tick(3); s.Leave(); p.SelectedMode = LinkMatchMode.Challenge; p.SelectedLevelId = "level-03"; p.Capture(s); Assert(p.SelectedMode == LinkMatchMode.Challenge && p.SelectedLevelId == "level-03", "Capturing a prior session rewrote the user's preview selection"); Eq(p.Export().Slots.Count(x => x != null), 1); });
        Check("the only win must be the best record's actual attempt", () => { var p = new LinkMatchProfile(); Win(p, 7, 2, 1); var root = JObject.Parse(LinkMatchSaveCodec.Encode(p.Export())); root["records"][3]["bestAttemptId"] = Guid.NewGuid().ToString("D"); Reject(root.ToString()); });
        Console.WriteLine("LinkMatch persistence/session: " + passed + " passed");
    }
    private static LinkMatchSession New(LinkMatchMode mode = LinkMatchMode.Relaxed) { return new LinkMatchSession(LinkMatchLevel.Get(1), mode, 17); }
    private static LinkMatchSession LastPair(LinkMatchMode mode, double elapsed) { var d = New(mode).Export(); d.Tiles = Enumerable.Repeat(-1, 24).ToArray(); d.Tiles[0] = d.Tiles[1] = 0; d.ElapsedSeconds = elapsed; d.RemainingSeconds = mode == LinkMatchMode.Challenge ? 90 - elapsed : 0; return new LinkMatchSession(d); }
    private static void Win(LinkMatchProfile p, double time, int hints, int shuffles) { var created = p.Start(LinkMatchMode.Challenge, "level-01", 7, true); var d = LastPair(LinkMatchMode.Challenge, time).Export(); d.AttemptId = created.AttemptId; d.HintsUsed = hints; d.ShufflesUsed = shuffles; var s = new LinkMatchSession(d); s.Enter(); Assert(s.TryMatch(0, 1, out var path)); p.Capture(s); }
    private static LinkMatchSaveData Fixture() { var p = new LinkMatchProfile(); var s = p.Start(LinkMatchMode.Relaxed, "level-01", 5); s.Enter(); s.Tick(4.25); p.Capture(s); return p.Export(); }
    private static void Mutate(string path, JToken value) { var root = JObject.Parse(LinkMatchSaveCodec.Encode(Fixture())); root.SelectToken(path).Replace(value); Reject(root.ToString()); }
    private static LinkMatchSaveData Decode(string json) { Assert(LinkMatchSaveCodec.TryDecode(json, out var data, out var reason), reason); return data; }
    private static void Reject(string json) { Assert(!LinkMatchSaveCodec.TryDecode(json, out var data, out var reason), "Invalid data accepted: " + json.Substring(0, Math.Min(100, json.Length))); Assert(data == null && reason != null); }
    private static void WithDirectory(Action<string> test) { string dir = Path.Combine(Path.GetTempPath(), "xanadu-link-match-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(dir); try { test(dir); } finally { Directory.Delete(dir, true); } }
    private static void Throws(Action action) { bool threw = false; try { action(); } catch (ArgumentException) { threw = true; } catch (InvalidOperationException) { threw = true; } Assert(threw, "Expected rejected input"); }
    private static void Eq(double actual, double expected) { Assert(Math.Abs(actual - expected) < 0.0000001, actual + " != " + expected); }
    private static void Assert(bool condition, string reason = "Assertion failed") { if (!condition) throw new Exception(reason); }
    private static void Check(string name, Action test) { test(); passed++; Console.WriteLine("PASS " + name); }
}
